# ─── Lexer ──────────────────────────────────────────────────────────────────

def _tokenize(text: str):
    """Metni tokendlere böler."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        # boşluk atla
        if text[i] in (' ', '\t', '\r'):
            i += 1
            continue
        # yorum: # den satır sonuna
        if text[i] == '#':
            while i < n and text[i] != '\n':
                i += 1
            continue
        # satır sonu (ifade ayırıcı)
        if text[i] == '\n':
            tokens.append(('\n', i))
            i += 1
            continue
        # tek karakterli tokenlar
        ch = text[i]
        if ch in ('(', ')', '+', '-', '*', '/', '%', ';', '='):
            tokens.append((ch, i))
            i += 1
            continue
        # nokta: ondalıklı sayı veya tek başına nokta
        if ch == '.':
            # ondalıklı sayı mı?
            if i + 1 < n and text[i + 1].isdigit():
                j = i + 1
                while j < n and text[j].isdigit():
                    j += 1
                tokens.append(('FLOAT', text[i:j], i))
                i = j
                continue
            else:
                raise SyntaxError(f"'.' beklenmiyor", i)
        # sayı
        if ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            # nokta var mı?
            if j < n and text[j] == '.':
                # ondalıklı
                j += 1
                while j < n and text[j].isdigit():
                    j += 1
                tokens.append(('FLOAT', text[i:j], i))
            else:
                tokens.append(('INT', text[i:j], i))
            i = j
            continue
        # isim (identifier)
        if ch.isalpha() or ch == '_':
            j = i + 1
            while j < n and (text[j].isalnum() or text[j] == '_'):
                j += 1
            tokens.append(('NAME', text[i:j], i))
            i = j
            continue
        raise SyntaxError(f"Bilinmeyen karakter: '{ch}'", i)
    return tokens


# ─── AST ────────────────────────────────────────────────────────────────────

class Num:
    __slots__ = ('value',)

    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f"Num({self.value})"


class BinOp:
    __slots__ = ('op', 'left', 'right')

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right


class UnaryOp:
    __slots__ = ('op', 'operand')

    def __init__(self, op, operand):
        self.op = op
        self.operand = operand


class Assign:
    __slots__ = ('name', 'value')

    def __init__(self, name, value):
        self.name = name
        self.value = value


class Expr:
    __slots__ = ('value',)

    def __init__(self, value):
        self.value = value


# ─── Parser (recursive descent) ─────────────────────────────────────────────

class Parser:
    """
    Aritmetik ifade parser'ı (precedence climbing).
    Program seviyesinde ifadeler ayrı ayrı parse edilir.

    Precedence (düşükten yükseğe):
      1. + -
      2. * / %
      3. unary + -
      4. **   (sağdan birleşen)
    """

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, type_):
        tok = self.peek()
        if tok is None:
            raise SyntaxError(f"'{type_}' bekleniyor",
                             self._pos_if_any())
        if tok[0] != type_:
            raise SyntaxError(f"'{type_}' bekleniyor, '{tok[0]}' bulundu",
                             self._pos_if_any())
        return self.advance()

    def _pos_if_any(self):
        try:
            return self.tokens[self.pos][2]
        except Exception:
            return 0

